import{d as c,C as t,o as g,c as u,j as a,a as o,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二十一章","description":"从孔德从道、恍惚有象与窈冥有信，追问万物发端所由。","frontmatter":{"title":"道德经第二十一章","description":"从孔德从道、恍惚有象与窈冥有信，追问万物发端所由。","category":"guide","aliases":["道德经第二十一章","老子第二十一章","dao de jing chapter 21"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-21.md","filePath":"daoism/dao-de-jing/chapter-21.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-21.md"},y=c({...b,setup(p){const s=[{id:"virtue-follows-dao",label:"孔德之容，惟道是从",showLabel:!0,sentences:[[{text:"孔",glossary:"kong"},"德之",{text:"容",glossary:"rong"},"，惟道是从。"]],note:["【白话】以虚空为德的形态，只依道而行。这一句先把德的呈现系于道，而不让它自立一套固定的作为。","【王弼注择要】「孔，空也。唯以空为德，然后乃能动作从道。」王弼将孔释为空，着眼于不先以自身的定式填满，才可能随道而动。","【读法】孔另有大义的解释，本页白话明确循王弼空义；容取形态、表现义，不取第十六章包容义。"]},{id:"indistinct-yet-generative",label:"惚兮恍兮，其中有象",showLabel:!0,sentences:[["道之为物，惟恍惟惚。"],[{text:"惚兮恍兮",glossary:"huhuang"},"，其中有",{text:"象",glossary:"xiang"},"；恍兮惚兮，其中有物。"]],note:["【白话】道作为所说的存在，恍恍惚惚，难以定形。惚啊恍啊，其中有象；恍啊惚啊，其中有物。它虽不呈现确定轮廓，却与万物的发端、成就相连。","【王弼注择要】「以无形始物，不系成物。」注又说「万物以始以成，而不知其所以然」，由万物确实发生、成就，却难知所由，解释恍惚之叹。","【读法】象在这里指形象、物象，不是第四章似、仿佛的动词义。惚兮恍兮与恍兮惚兮是反复咏叹，不是两项可分离测量的状态。"]},{id:"deep-yet-trustworthy",label:"窈兮冥兮，其中有精",showLabel:!0,sentences:[[{text:"窈兮冥兮",glossary:"yaoming"},"，其中有",{text:"精",glossary:"jing"},"；其精甚真，其中有",{text:"信",glossary:"xin"},"。"]],note:["【白话】幽深啊，昏冥啊，其中有精微的实质；这精微的实质十分真实，其中有可以信验的根据。道虽深远难见，万物由之而成这一面并不虚妄。","【王弼注择要】「窈冥，深远之叹。」信字注释「信，信验也」，并以「万物之性定」说明真与信：深远难见，仍可由万物成其性来认识。","【读法】精在此依真、信与生成为精微实质来读，不据以认定某种粒子、能量或体内物质；信取信验义，与第十七章诚信、信任义分开。"]},{id:"tracing-the-beginnings",label:"吾何以知众甫之状哉",showLabel:!0,sentences:[["自今及古，其名不去，以",{text:"阅",glossary:"yue"},{text:"众甫",glossary:"zhongfu"},"。"],["吾何以知众甫之状哉？以此。"]],note:["【白话】从今天追溯到古时，它的名始终不消失，可以凭此察看万物的发端。我凭什么知道万物发端的情状呢？就凭上面所说的这些。","【王弼注择要】众甫，注释「物之始也」；以此，注说「此，上之所云也」。其名又连「无名则是其名也」理解，不是把道定成一个普通事物的名称。","【读法】本站保留自今及古；所据录文作自古及今。以此回指上文对生成所由的讨论，不是凭一句自我断言便免除说明。"]}],r=[{id:"kong",term:"孔",sense:1},{id:"rong",term:"容",sense:1},{id:"huhuang",term:"惚恍",sense:1},{id:"xiang",term:"象",sense:2},{id:"yaoming",term:"窈冥",sense:1},{id:"jing",term:"精",sense:1},{id:"xin",term:"信",sense:2},{id:"yue",term:"阅",sense:1},{id:"zhongfu",term:"众甫",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十一章",tabindex:"-1"},[o("道德经第二十一章 "),a("a",{class:"header-anchor",href:"#道德经第二十一章","aria-label":'Permalink to "道德经第二十一章"'},"​")],-1)),n(i,{title:"恍惚之中，怎样追问万物所由",summary:"本章先说德的形态随道而行，再以恍惚、窈冥写道难以定形，却又有象、有物、有精、有信；末尾回问，凭什么认识万物的发端。",points:[{label:"先读",text:"将恍惚、窈冥与其中有相连，感受难以定形而并非空无所有。"},{label:"再辨",text:"象、精、信各有语境，不把它们套成现代物理实体。"},{label:"后看",text:"以此回指上文，追问从生成的作用认识其所由的思路。"}],hint:"孔字本页循王弼空义读；自今及古保留本站正文，异文见篇末。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),n(l,{sections:s,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"孔德之容，惟道是从。",tone:"德与道",guide:"先循王弼空义看从道的条件，再辨通行的大德解释；不要略去注家的取径。"},{text:"窈兮冥兮，其中有精；其精甚真，其中有信。",tone:"深远与信验",guide:"有精、有信使深远难见不止于模糊想象；解释仍要返回万物由之而成。"},{text:"吾何以知众甫之状哉？以此。",tone:"回问根据",guide:"以此回指前文，提醒读者追问认识所凭，而不是只接受一个名词。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,y as default};
